const LF = String.fromCharCode(10);
const items = $input.all();
const detections = [];
for (const it of items) {
  const v = it.json && it.json.value;
  if (Array.isArray(v)) { detections.push(...v); }
  else if (it.json && it.json.id) { detections.push(it.json); }
}
const high = detections.filter(d => String(d.riskLevel || '').toLowerCase() === 'high');
const byUser = {};
for (const d of high) {
  const key = d.userPrincipalName || d.userDisplayName || d.userId || 'unknown';
  if (!byUser[key]) {
    byUser[key] = { user: key, userDisplayName: d.userDisplayName || '', userPrincipalName: d.userPrincipalName || '', userId: d.userId || '', detections: [] };
  }
  byUser[key].detections.push(d);
}
const uniq = (arr) => [...new Set(arr.filter(Boolean))];
const results = [];
for (const key of Object.keys(byUser)) {
  const g = byUser[key];
  const ds = g.detections;
  const riskLevels = uniq(ds.map(d => d.riskLevel));
  const riskStates = uniq(ds.map(d => d.riskState));
  const detectionTypes = uniq(ds.map(d => d.riskEventType || d.riskType));
  const ips = uniq(ds.map(d => d.ipAddress));
  const countries = uniq(ds.map(d => (d.location || {}).countryOrRegion));
  const locations = uniq(ds.map(d => { const l = d.location || {}; return [l.city, l.state, l.countryOrRegion].filter(Boolean).join(', '); }));
  const detectedTimes = ds.map(d => d.detectedDateTime).filter(Boolean).sort();
  results.push({
    json: {
      user: g.userDisplayName || g.user,
      userPrincipalName: g.userPrincipalName || g.user,
      userId: g.userId,
      detectionCount: ds.length,
      riskLevels, riskStates, detectionTypes, ips, countries, locations,
      firstDetected: detectedTimes[0] || '',
      lastDetected: detectedTimes[detectedTimes.length - 1] || '',
      detections: ds,
    },
  });
}
return results;

const LF = String.fromCharCode(10);
const users = $('Group & Aggregate Per User').all().map(i => i.json);
const risky = $('Enrich Risky User').all().map(i => i.json);
const signinItems = $('Enrich Recent Sign-Ins').all().map(i => i.json);

const riskyById = {};
for (const r of risky) { if (r && r.id) riskyById[r.id] = r; }
const signinsById = {};
for (const s of signinItems) {
  const arr = Array.isArray(s.value) ? s.value : [];
  const uid = s._userId || (arr[0] && arr[0].userId);
  if (uid) signinsById[uid] = arr;
}

const explainType = (t) => {
  const m = {
    unfamiliarFeatures: 'sign-in with unfamiliar properties for this user',
    anonymizedIPAddress: 'sign-in from an anonymized IP (e.g. Tor/VPN)',
    maliciousIPAddress: 'sign-in from a known malicious IP',
    malwareInfectedIPAddress: 'sign-in from a malware-infected IP',
    suspiciousIPAddress: 'sign-in from a suspicious IP',
    leakedCredentials: 'credentials found leaked publicly',
    impossibleTravel: 'impossible travel between sign-ins',
    newCountry: 'sign-in from a new country',
    passwordSpray: 'password-spray pattern detected',
  };
  return m[t] || t;
};

const results = [];
for (const u of users) {
  const r = riskyById[u.userId] || {};
  const signins = signinsById[u.userId] || [];
  const roles = Array.isArray(r.assignedRoles) ? r.assignedRoles : [];
  const rolesText = roles.join(', ');
  const isPrivileged = /admin|administrator|global|security|privileged/i.test((r.jobTitle || '') + ' ' + rolesText);

  // ---- deterministic correlation signals ----
  const reasons = [];
  if (u.detectionCount > 1) reasons.push('Multiple high-risk detections (' + u.detectionCount + ') for the same user');
  if ((u.ips || []).length > 1) reasons.push('Multiple source IPs (' + u.ips.join(', ') + ')');
  if ((u.countries || []).length > 1) reasons.push('Sign-ins from multiple countries (' + u.countries.join(', ') + ') — possible impossible travel');
  if ((u.detectionTypes || []).length > 1) reasons.push('Multiple distinct detection types (' + u.detectionTypes.join(', ') + ')');
  if ((u.riskStates || []).includes('confirmedCompromised')) reasons.push('Risk state confirmedCompromised');
  if (isPrivileged) reasons.push('Privileged/admin account (' + (r.jobTitle || rolesText || 'elevated role') + ')');
  const anyDevNonCompliant = signins.some(s => s.deviceDetail && s.deviceDetail.isCompliant === false);
  if (anyDevNonCompliant) reasons.push('Sign-in from a non-compliant device');

  // ---- deterministic escalation decision ----
  const especiallySuspicious = isPrivileged
    || (u.riskStates || []).includes('confirmedCompromised')
    || (u.countries || []).length > 1
    || reasons.length >= 3;
  const decision = especiallySuspicious ? 'ESPECIALLY SUSPICIOUS' : 'STANDARD HIGH-RISK';
  const severity = especiallySuspicious ? 4 : 3;
  const severityLabel = especiallySuspicious ? 'CRITICAL' : 'HIGH';

  // ---- enrichment lines ----
  const enrich = [];
  enrich.push('Account enabled: ' + (r.accountEnabled === undefined ? 'unknown' : r.accountEnabled));
  enrich.push('Job title: ' + (r.jobTitle || 'unknown') + (r.department ? (' | Dept: ' + r.department) : ''));
  enrich.push('Directory roles: ' + (rolesText || 'none'));
  enrich.push('Risky-user state: ' + (r.riskState || 'n/a') + ' (updated ' + (r.riskLastUpdatedDateTime || 'n/a') + ')');
  if (signins.length) {
    const s0 = signins[0];
    const dev = s0.deviceDetail || {};
    const loc = s0.location || {};
    enrich.push('Latest sign-in: ' + (s0.appDisplayName || 'app?') + ' from ' + (s0.ipAddress || 'ip?') + ' [' + [loc.city, loc.countryOrRegion].filter(Boolean).join(', ') + ']');
    enrich.push('Device: ' + [dev.browser, dev.operatingSystem].filter(Boolean).join(' / ') + (dev.isCompliant === false ? ' (non-compliant)' : ''));
  } else {
    enrich.push('Recent sign-ins: none returned');
  }

  // ---- short "why flagged" explanation ----
  const whyFlagged = (u.detectionTypes || []).map(explainType).join('; ');

  // ---- investigation summary ----
  const summary = 'User ' + u.user + ' (' + u.userPrincipalName + ') generated ' + u.detectionCount
    + ' high-risk Entra ID detection(s) between ' + (u.firstDetected || '?') + ' and ' + (u.lastDetected || '?')
    + ' from ' + (u.ips || []).length + ' IP(s) across ' + (u.countries || []).join('/') + '. Classified ' + decision + '.';

  // ---- full TheHive description ----
  const L = [];
  L.push('## Entra ID High-Risk User Incident');
  L.push('Classification: ' + decision + ' (severity ' + severityLabel + ')');
  L.push('');
  L.push('### WHO');
  L.push('User: ' + u.user + ' (' + u.userPrincipalName + ')');
  L.push('User ID: ' + (u.userId || 'n/a'));
  L.push('Privileged: ' + (isPrivileged ? 'YES' : 'no'));
  L.push('');
  L.push('### WHAT');
  L.push('High-risk detections: ' + u.detectionCount);
  L.push('Risk level(s): ' + (u.riskLevels || []).join(', '));
  L.push('Risk state(s): ' + (u.riskStates || []).join(', '));
  L.push('Detection type(s): ' + (u.detectionTypes || []).join(', '));
  L.push('Why flagged: ' + whyFlagged);
  L.push('');
  L.push('### WHERE');
  L.push('IP address(es): ' + ((u.ips || []).join(', ') || 'n/a'));
  L.push('Location(s): ' + ((u.locations || []).join(' | ') || 'n/a'));
  L.push('');
  L.push('### WHEN');
  L.push('First detected: ' + (u.firstDetected || 'n/a'));
  L.push('Last detected: ' + (u.lastDetected || 'n/a'));
  L.push('');
  L.push('### ENRICHMENT');
  for (const e of enrich) L.push('- ' + e);
  L.push('');
  L.push('### CORRELATION / ESCALATION REASONS');
  if (reasons.length) { for (const rr of reasons) L.push('- ' + rr); } else { L.push('- Single isolated high-risk detection'); }
  L.push('');
  L.push('### INVESTIGATION SUMMARY');
  L.push(summary);
  L.push('');
  L.push('### PER-DETECTION DETAIL');
  (u.detections || []).forEach((d, i) => {
    const l = d.location || {};
    const loc = [l.city, l.state, l.countryOrRegion].filter(Boolean).join(', ');
    L.push('  ' + (i + 1) + '. ' + (d.riskEventType || d.riskType || 'unknown') + ' | state=' + (d.riskState || 'n/a') + ' | ip=' + (d.ipAddress || 'n/a') + ' | loc=' + (loc || 'n/a') + ' | detected=' + (d.detectedDateTime || 'n/a'));
  });

  const description = L.join(LF);
  const sourceRef = 'entra-highrisk-' + u.userPrincipalName; // stable per ongoing incident (enables dedup)

  results.push({ json: {
    user: u.user, userPrincipalName: u.userPrincipalName, userId: u.userId,
    detectionCount: u.detectionCount, riskLevels: u.riskLevels, riskStates: u.riskStates,
    detectionTypes: u.detectionTypes, ips: u.ips, locations: u.locations, countries: u.countries,
    firstDetected: u.firstDetected, lastDetected: u.lastDetected,
    primaryIp: (u.ips || [])[0] || '',
    isPrivileged, decision, especiallySuspicious, severity, severityLabel,
    whyFlagged, reasons, summary, description, sourceRef,
  }});
}
return results;

const users = $('Assess, Correlate & Build Incident').all().map(i => i.json);
const openAlerts = $('Query Open TheHive Alerts').all().map(i => i.json).filter(a => a && a.sourceRef);
const bySourceRef = {};
for (const a of openAlerts) { bySourceRef[a.sourceRef] = a; }
return users.map(u => {
  const existing = bySourceRef[u.sourceRef];
  return { json: Object.assign({}, u, {
    alertExists: !!existing,
    existingAlertId: existing ? (existing._id || existing.id || '') : '',
  }) };
});

const LF = String.fromCharCode(10);
const resp = $json || {};
const ctx = $('Deduplication Decision').item.json;
const alertId = resp._id || ctx.existingAlertId || 'unknown';
const action = ctx.alertExists ? 'UPDATED' : 'CREATED';
const emoji = ctx.especiallySuspicious ? ':rotating_light:' : ':warning:';

const lines = [];
lines.push(emoji + ' *Entra ID high-risk user ' + (ctx.especiallySuspicious ? '(ESPECIALLY SUSPICIOUS)' : '') + '*');
lines.push('*User:* ' + ctx.user + ' (' + ctx.userPrincipalName + ')');
lines.push('*Risk level:* ' + (ctx.riskLevels || []).join(', ') + '  |  *State:* ' + (ctx.riskStates || []).join(', '));
lines.push('*Detection types:* ' + (ctx.detectionTypes || []).join(', '));
lines.push('*IP(s):* ' + ((ctx.ips || []).join(', ') || 'n/a'));
lines.push('*Location(s):* ' + ((ctx.locations || []).join(' | ') || 'n/a'));
lines.push('*First seen:* ' + (ctx.firstDetected || 'n/a') + '  |  *Last seen:* ' + (ctx.lastDetected || 'n/a'));
lines.push('*Why flagged:* ' + (ctx.whyFlagged || 'n/a'));
lines.push('*TheHive alert:* ' + action + ' — ref `' + ctx.sourceRef + '` (id: ' + alertId + ')');
const slackText = lines.join(LF);
return { json: Object.assign({}, ctx, { alertId, action, slackText }) };
